
if (typeof window !== "undefined") {
  window.__openSupplierModal = function(data) {
    try {
      var old = document.getElementById("supplier-modal-container");
      if (old) old.remove();
      var isKasra = data.supplierName === "کسری پلاس";
      var modal = document.createElement("div");
      modal.id = "supplier-modal-container";
      modal.className = "fixed inset-0 z-[99999] flex items-center justify-center p-3 sm:p-6 bg-slate-950/80 backdrop-blur-sm animate-fadeIn";
      modal.dir = "rtl";
      modal.innerHTML = '<div class="relative w-full max-w-4xl bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden flex flex-col max-h-[92vh]">' +
        '<div class="px-5 py-4 bg-slate-50 border-b border-slate-200 flex items-center justify-between gap-3">' +
          '<div class="flex items-center gap-2.5 min-w-0">' +
            '<span class="px-2.5 py-1 rounded-lg text-xs font-black ' + (isKasra ? 'bg-indigo-100 text-indigo-700' : 'bg-emerald-100 text-emerald-700') + '">' + data.supplierName + '</span>' +
            '<span class="font-bold text-xs sm:text-sm text-slate-800 truncate">' + (data.productName || 'صفحه تامین‌کننده') + '</span>' +
          '</div>' +
          '<div class="flex items-center gap-2 shrink-0">' +
            '<a href="' + data.url + '" target="_blank" rel="noreferrer" class="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-white text-xs font-bold shadow-xs">مشاهده در ' + data.supplierName + ' ↗</a>' +
            '<button type="button" id="close-supplier-modal-btn" class="flex items-center gap-1.5 px-3.5 py-1.5 rounded-xl bg-rose-50 hover:bg-rose-100 text-rose-600 text-xs font-bold transition-all cursor-pointer border border-rose-200 shadow-xs">' +
              '<span class="text-base font-black leading-none">✕</span>' +
              '<span>بستن</span>' +
            '</button>' +
          '</div>' +
        '</div>' +
        '<div class="flex-1 w-full bg-slate-100 relative min-h-[480px] flex flex-col">' +
          '<div class="p-3 bg-amber-50 border-b border-amber-200 text-amber-900 text-xs flex items-center justify-between gap-2">' +
            '<span>در حال نمایش صفحه کالا در سایت ' + data.supplierName + '</span>' +
            '<a href="' + data.url + '" target="_blank" rel="noreferrer" class="text-amber-800 font-bold underline shrink-0">باز کردن مستقیم در تب جدید ↗</a>' +
          '</div>' +
          '<iframe src="' + data.url + '" title="صفحه تامین کننده" class="w-full flex-1 border-0 min-h-[440px] bg-white" sandbox="allow-same-origin allow-scripts allow-forms allow-popups"></iframe>' +
        '</div>' +
      '</div>';
      document.body.appendChild(modal);
      var btn = document.getElementById("close-supplier-modal-btn");
      if (btn) btn.onclick = function() { modal.remove(); };
      modal.onclick = function(e) { if (e.target === modal) modal.remove(); };
    } catch(err) { console.error("Error opening supplier modal:", err); }
  };
}
